if (this._checked) {
  if ('email_cty,email_ca_nhan'.indexOf(',') == -1) {
    var label = $func.findField('email_cty,email_ca_nhan', this._fields).Label;
    var e = ((this._language == 'v') ? 'Trường <span class="Highlight">' + label + '</span> không hợp lệ.' : 'Invalid <span class="Highlight">' + label + '</span>.');
    if !(checkValidEmail$Test(this, 'email_cty,email_ca_nhan', true)) {
      this._checked = false;
      var o = this.getItem('email_cty,email_ca_nhan');
      $func.hideWait(this.get_id());
      $message.show(e, String.format('$find(\'{0}\').focus(\'{1}\');', this._id, o.field.Name));
    }
  } else {
    var _$fieldNames = 'email_cty,email_ca_nhan'.split(',');
    for (var i = 0; i < _$fieldNames.length; i++) {
      var label = $func.findField(_$fieldNames[i], this._fields).Label;
      var e = ((this._language == 'v') ? 'Trường <span class="Highlight">' + label + '</span> không hợp lệ.' : 'Invalid <span class="Highlight">' + label + '</span>.');
      if (this._checked) {
        if !(checkValidEmail$Test(this, _$fieldNames[i], true)) {
          this._checked = false;
          var o = this.getItem(_$fieldNames[i]);
          $func.hideWait(this.get_id());
          $message.show(e, String.format('$find(\'{0}\').focus(\'{1}\');', this._id, o.field.Name));
        }
      } else break;
    }
  }
}

